CREATE TABLE IF NOT EXISTS hosts(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS events(id BIGINT PRIMARY KEY AUTO_INCREMENT,host_id BIGINT NOT NULL,type ENUM('CONCERT','SPORTS','MOVIE') NOT NULL,title VARCHAR(140) NOT NULL,venue VARCHAR(180) NOT NULL,description TEXT NOT NULL,image VARCHAR(50) NOT NULL,starts_at DATETIME NOT NULL,early_bird_until DATETIME NOT NULL,base_price DECIMAL(10,2) NOT NULL,published BOOLEAN NOT NULL DEFAULT 0,FOREIGN KEY(host_id) REFERENCES hosts(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS venue_layouts(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL UNIQUE,grid_rows INT NOT NULL,grid_cols INT NOT NULL,stage_row INT NOT NULL,stage_col INT NOT NULL,stage_width INT NOT NULL,FOREIGN KEY(event_id) REFERENCES events(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sections(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,category ENUM('REGULAR','VIP') NOT NULL,color CHAR(7) NOT NULL,UNIQUE(event_id,category),FOREIGN KEY(event_id) REFERENCES events(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS seats(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,section_id BIGINT NOT NULL,row_no INT NOT NULL,col_no INT NOT NULL,label VARCHAR(12) NOT NULL,status ENUM('AVAILABLE','SOLD') NOT NULL DEFAULT 'AVAILABLE',UNIQUE(event_id,row_no,col_no),FOREIGN KEY(event_id) REFERENCES events(id),FOREIGN KEY(section_id) REFERENCES sections(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tickets(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(30) NOT NULL UNIQUE,event_id BIGINT NOT NULL,customer_id BIGINT NOT NULL,seat_id BIGINT NULL,seat_label VARCHAR(12) NOT NULL,category ENUM('REGULAR','VIP','EARLY_BIRD') NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('VALID','USED','CANCELLED') NOT NULL,issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,active_seat BIGINT GENERATED ALWAYS AS (CASE WHEN status IN ('VALID','USED') THEN seat_id ELSE NULL END) STORED,UNIQUE(active_seat),FOREIGN KEY(event_id) REFERENCES events(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(seat_id) REFERENCES seats(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL UNIQUE,method ENUM('CASH','EWALLET','CARD') NOT NULL,reference VARCHAR(80) NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,status ENUM('SIMULATED_SUCCESS','SIMULATED_REFUNDED') NOT NULL,FOREIGN KEY(ticket_id) REFERENCES tickets(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS receipts(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL UNIQUE,payment_id BIGINT NOT NULL UNIQUE,number VARCHAR(40) NOT NULL UNIQUE,FOREIGN KEY(ticket_id) REFERENCES tickets(id),FOREIGN KEY(payment_id) REFERENCES payments(id)) ENGINE=InnoDB;

-- Apply once before running the flexible venue edition. Existing records are preserved.
ALTER TABLE sections MODIFY category VARCHAR(40) NOT NULL;
ALTER TABLE sections ADD COLUMN IF NOT EXISTS ticket_name VARCHAR(50) NULL;
ALTER TABLE sections ADD COLUMN IF NOT EXISTS ticket_price DECIMAL(10,2) NULL;
ALTER TABLE sections ADD COLUMN IF NOT EXISTS early_bird BOOLEAN NOT NULL DEFAULT 0;
ALTER TABLE seats ADD COLUMN IF NOT EXISTS area_code VARCHAR(30) NULL;
ALTER TABLE seats MODIFY label VARCHAR(64) NOT NULL;
ALTER TABLE tickets MODIFY seat_label VARCHAR(64) NOT NULL;
ALTER TABLE tickets MODIFY category VARCHAR(80) NOT NULL;
CREATE TABLE IF NOT EXISTS venue_plans(event_id BIGINT PRIMARY KEY,stage_x INT NOT NULL,stage_y INT NOT NULL,stage_width INT NOT NULL,stage_height INT NOT NULL,FOREIGN KEY(event_id) REFERENCES events(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS venue_areas(event_id BIGINT NOT NULL,code VARCHAR(30) NOT NULL,name VARCHAR(40) NOT NULL,type_code VARCHAR(40) NOT NULL,x INT NOT NULL,y INT NOT NULL,width INT NOT NULL,height INT NOT NULL,seat_rows INT NOT NULL,seat_columns INT NOT NULL,row_offset INT NOT NULL,shape VARCHAR(12) NOT NULL,blocked_cells TEXT NOT NULL,PRIMARY KEY(event_id,code),FOREIGN KEY(event_id) REFERENCES events(id)) ENGINE=InnoDB;

-- Optional overview color; existing sections keep the ticket-type color.
ALTER TABLE venue_areas ADD COLUMN IF NOT EXISTS area_color CHAR(7) NULL;
